const params=new URLSearchParams(location.search),requested=params.get('species')||'mango',language=localStorage.getItem('tfruitllm-language')==='zh'?'zh':'en';
const root=document.querySelector('#genomeContent'),back=document.querySelector('#resourceBack');
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const text={en:{back:'Research resources',catalog:'PUBLIC GENOME ASSEMBLIES',assemblies:'NCBI assemblies',updated:'NCBI data updated',switchSpecies:'Switch species',modelTitle:'Genome version used by TropicalfruitLLM v1.0',modelBody:'No single fixed genome assembly. The model was fine-tuned from literature, question-answer and multi-omics evidence; its weights are not built from or bound to one unified genome FASTA. For reproducible analysis, cite the exact assembly accession used.',otherTitle:'Other genome repositories',otherBody:'Search additional primary repositories and international mirrors for this species. ENA and DDBJ participate in INSDC, so many records mirror the same assemblies listed by NCBI and are not counted again.',gwh:'NGDC Genome Warehouse',cngb:'CNGBdb',ena:'ENA assemblies',ddbj:'DDBJ',phytozome:'JGI Phytozome',public:'NCBI public assembly',accession:'Accession',name:'Assembly name',sample:'Cultivar / isolate',level:'Assembly level',date:'Release date',project:'BioProject',record:'NCBI record',download:'Download genome',empty:'No public assembly is currently listed for this species.'},zh:{back:'返回研究资源',catalog:'公开基因组组装目录',assemblies:'个 NCBI 组装版本',updated:'NCBI 数据更新于',switchSpecies:'切换物种',modelTitle:'TropicalfruitLLM v1.0 使用的基因组版本',modelBody:'未绑定单一固定基因组版本。模型基于文献、问答与多组学证据微调，模型权重并非由某一个统一的基因组 FASTA 组装构建。涉及可复现分析时，应明确引用实际使用的组装登录号。',otherTitle:'其他基因组数据库',otherBody:'继续在其他原始数据库和国际镜像中检索该物种。ENA 与 DDBJ 属于 INSDC 协作体系，许多记录与 NCBI 为同一组装的镜像，因此不重复计入版本总数。',gwh:'NGDC Genome Warehouse',cngb:'CNGBdb 国家基因库',ena:'ENA 基因组组装',ddbj:'DDBJ 日本数据库',phytozome:'JGI Phytozome',public:'NCBI 公开组装',accession:'登录号',name:'组装名称',sample:'品种 / 样本',level:'组装层级',date:'发布日期',project:'BioProject',record:'NCBI 记录',download:'下载基因组',empty:'NCBI 当前未列出该物种的公开组装。'}}[language];
document.documentElement.lang=language==='zh'?'zh-CN':'en';back.textContent=text.back;
const sampleLabel=assembly=>[assembly.cultivar,assembly.isolate&&`isolate=${assembly.isolate}`].filter(Boolean).join(' · ')||'—';
fetch('data/genomes.json').then(response=>response.json()).then(data=>{
  const species=data.species.find(item=>item.key===requested)||data.species[0],assemblies=species.assemblies||[];
  document.title=`${species.commonName} Genome Assemblies | TropicalfruitLLM v1.0`;
  const speciesOptions=data.species.map(item=>`<option value="${esc(item.key)}"${item.key===species.key?' selected':''}>${esc(item.commonName)} · ${esc(item.scientificName)} (${item.assemblies.length})</option>`).join('');
  const query=encodeURIComponent(species.scientificName),taxid=encodeURIComponent(species.taxid||species.scientificName);
  const repositories=[
    [text.gwh,`https://ngdc.cncb.ac.cn/gwh/search/advanced`,'GWH / NGDC'],
    [text.cngb,`https://db.cngb.org/search/?q=${query}`,'CNGBdb'],
    [text.ena,`https://www.ebi.ac.uk/ena/browser/advanced-search?query=tax_tree(${taxid})&result=assembly`,'INSDC mirror'],
    [text.ddbj,`https://ddbj.nig.ac.jp/search/entry?database=assembly&query=${query}`,'INSDC mirror'],
    [text.phytozome,'https://phytozome-next.jgi.doe.gov/','Plant comparative genomics']
  ];
  root.innerHTML=`<section class="genome-heading"><div class="genome-heading-row"><div><p class="eyebrow">${text.catalog}</p><h1>${esc(species.commonName)}</h1><p class="scientific-name">${esc(species.scientificName)}</p></div><label class="genome-species-switch"><span>${text.switchSpecies}</span><select id="genomeSpeciesSelect">${speciesOptions}</select></label></div><div class="genome-summary"><strong>${assemblies.length}</strong><span>${text.assemblies}</span><small>${text.updated} ${esc(data.updated)}</small></div></section><section class="model-genome-note"><span>MODEL GENOME STATUS</span><div><h2>${text.modelTitle}</h2><p>${text.modelBody}</p></div></section><section class="external-genomes"><div><span>EXTERNAL REPOSITORIES</span><h2>${text.otherTitle}</h2><p>${text.otherBody}</p></div><div class="repository-links">${repositories.map(([label,url,note])=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer"><strong>${esc(label)}</strong><small>${esc(note)}</small></a>`).join('')}</div></section><section class="assembly-section"><div class="assembly-list">${assemblies.length?assemblies.map(assembly=>`<article class="assembly-card"><header><span>${text.public}</span><strong>${esc(assembly.accession)}</strong></header><dl><div><dt>${text.name}</dt><dd>${esc(assembly.assemblyName||'—')}</dd></div><div><dt>${text.sample}</dt><dd>${esc(sampleLabel(assembly))}</dd></div><div><dt>${text.level}</dt><dd>${esc(assembly.level||'—')}</dd></div><div><dt>${text.date}</dt><dd>${esc(assembly.releaseDate||'—')}</dd></div><div><dt>${text.project}</dt><dd>${esc(assembly.bioproject||'—')}</dd></div></dl><footer><a href="${esc(assembly.ncbiUrl)}" target="_blank" rel="noopener noreferrer">${text.record}</a><a class="primary" href="${esc(assembly.downloadUrl||assembly.ncbiUrl)}" target="_blank" rel="noopener noreferrer">${text.download}</a></footer></article>`).join(''):`<p class="empty-assemblies">${text.empty}</p>`}</div></section>`;
  document.querySelector('#genomeSpeciesSelect').addEventListener('change',event=>{location.href=`genomes.html?species=${encodeURIComponent(event.target.value)}`});
}).catch(()=>{root.innerHTML='<p class="loading">Genome assembly data are temporarily unavailable.</p>'});
